<!doctype html><html lang="en"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#17212c}h1{font-size:23px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{text-align:left;padding:10px 6px;border-bottom:1px solid #ddd}p{line-height:1.6}</style></head><body><h1>Dues statement</h1><p>{{ $tenant->name }}<br>{{ $member->name }}<br>Charge periods beginning {{ $from }} to {{ $to }}</p><table><thead><tr><th>Period</th><th>Amount</th><th>State</th><th>Payment</th></tr></thead><tbody>@forelse($charges as $charge)<tr><td>{{ $charge->period_start->format('d M Y') }} – {{ $charge->period_end->format('d M Y') }}</td><td>{{ $charge->currency }} {{ number_format($charge->amount / 100, 2) }}</td><td>{{ $charge->status->label() }}</td><td>{{ $charge->payment_method ?? '—' }}<br>{{ $charge->paid_at?->format('d M Y') ?? '—' }}</td></tr>@empty<tr><td colspan="4">No recorded charges for this period.</td></tr>@endforelse</tbody></table><p>This statement reflects recorded dues charges and their current states. It is not a cash balance or a payment receipt. Currencies are shown separately.</p>@if(isset($givingRows) && $givingRows->isNotEmpty())<h2>Contributions</h2><p>Voluntary contributions attributed to this member and dated adjustments. These are separate from dues and do not create an amount owed.</p><table><thead><tr><th>Date</th><th>Fund / record</th><th>Amount</th></tr></thead><tbody>@foreach($givingRows as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['fund'] }}<br>{{ str_replace('_',' ',$row['kind']) }}@if($row['member_name'])<br>For {{ $row['member_name'] }} ({{ $row['access_role'] }})@endif</td><td>{{ $row['currency'] }} {{ number_format($row['amount']/100,2) }}</td></tr>@endforeach</tbody></table>@endif</body></html>
